create table public.dimension_rng_configs(id bigint generated always as identity primary key,dimension_id uuid not null references public.dimension_presets(id)on delete cascade,mechanic_slug text not null check(mechanic_slug in('item_rarity','random_encounter','monster_elite','quest_reward')),mode text not null check(mode in('pure','protected')),pity_threshold smallint check((mode='pure'and pity_threshold is null)or(mode='protected'and pity_threshold between 2 and 100)),success_chance smallint not null check(success_chance between 1 and 99),unique(dimension_id,mechanic_slug));
create table public.character_rng_pity(character_id uuid not null references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,mechanic_slug text not null,consecutive_failures integer not null default 0 check(consecutive_failures>=0),updated_at timestamptz not null default now(),primary key(character_id,mechanic_slug));
alter table public.dimension_rng_configs enable row level security;alter table public.character_rng_pity enable row level security;
create policy "Players read dimension RNG rules"on public.dimension_rng_configs for select to authenticated using(true);create policy "Players read own pity counters"on public.character_rng_pity for select to authenticated using(user_id=auth.uid());
insert into public.dimension_rng_configs(dimension_id,mechanic_slug,mode,pity_threshold,success_chance)select preset.id,mechanic.slug,case when preset.slug='twin-star-abyss'then'pure'else'protected'end,case when preset.slug='twin-star-abyss'then null when preset.slug='umbra-veil'then mechanic.hard_threshold else mechanic.normal_threshold end,mechanic.chance from public.dimension_presets preset cross join(values('item_rarity',8,12,15),('random_encounter',6,9,25),('monster_elite',10,15,10),('quest_reward',5,8,20))as mechanic(slug,normal_threshold,hard_threshold,chance);
create or replace function public.roll_dimension_rng(target_character_id uuid,target_mechanic text,target_chance integer default null)returns jsonb language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;config public.dimension_rng_configs%rowtype;state public.character_rng_pity%rowtype;chance integer;rolled integer;success boolean;forced boolean:=false;failures integer:=0;begin select*into hero from public.characters where id=target_character_id and user_id=auth.uid();if hero.id is null then raise exception'character not found';end if;select*into config from public.dimension_rng_configs where dimension_id=hero.dimension_id and mechanic_slug=target_mechanic;if config.id is null then raise exception'mechanic not configured';end if;chance:=coalesce(target_chance,config.success_chance);if chance not between 1 and 99 then raise exception'invalid chance';end if;if config.mode='protected'then insert into public.character_rng_pity(character_id,user_id,mechanic_slug)values(hero.id,hero.user_id,target_mechanic)on conflict do nothing;select*into state from public.character_rng_pity where character_id=hero.id and mechanic_slug=target_mechanic for update;failures:=state.consecutive_failures;forced:=failures>=config.pity_threshold-1;end if;rolled:=floor(random()*100)::integer+1;success:=forced or rolled<=chance;if config.mode='protected'then update public.character_rng_pity set consecutive_failures=case when success then 0 else consecutive_failures+1 end,updated_at=now()where character_id=hero.id and mechanic_slug=target_mechanic returning*into state;failures:=state.consecutive_failures;end if;return jsonb_build_object('mode',config.mode,'mechanic',target_mechanic,'success',success,'forced_by_pity',forced,'roll',rolled,'chance',chance,'failures_after',failures,'pity_threshold',config.pity_threshold);end;$$;
revoke all on function public.roll_dimension_rng(uuid,text,integer)from public;grant execute on function public.roll_dimension_rng(uuid,text,integer)to authenticated;
